//! Acceptance criteria of spec node CORE.BUS.UNIT (AC-1 .. AC-5, and the platform-independent
//! part of AC-6). Expected values come from `fixtures/core/bus/unit/make_literals.py`, an exact
//! rational reference written in Python; nothing here is generated by this crate.
#![allow(clippy::unwrap_used, clippy::expect_used, clippy::panic)]

use fid_bus::error::{BusError, Code, ValidationReason};
use fid_bus::unit::{
    algorithm_id, normalise, normalise_value, AuthoredLiteral, DecimalString, UnitSymbol, ALGORITHM, MAX_SIG_DIGITS,
};
use fid_canon::{to_canonical_bytes, CValue};
use fid_registry::{Catalogue, QuantityCatalogue};
use std::collections::BTreeMap;
use std::path::{Path, PathBuf};

const DIR: &str = "fixtures/core/bus/unit";

fn root() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../..")
}

fn read(name: &str) -> Vec<u8> {
    std::fs::read(root().join(DIR).join(name)).unwrap_or_else(|e| panic!("{name}: {e}"))
}

fn fixture_catalogue() -> Catalogue {
    Catalogue::from_json(&read("catalogue.json")).unwrap_or_else(|e| panic!("catalogue.json: {e}"))
}

fn geo() -> Catalogue {
    Catalogue::geo_frame().unwrap_or_else(|e| panic!("{e}"))
}

/// Literal and unit, then normalisation: what VALID does for one parameter.
fn run(value: &str, unit: &str, kind: &str, cat: &dyn QuantityCatalogue) -> Result<u64, BusError> {
    let lit = AuthoredLiteral::new(value, unit)?;
    normalise(&lit, kind, cat).map(|n| n.si_bits())
}

fn validation(reason: ValidationReason) -> impl Fn(&BusError) -> bool {
    move |e| matches!(e, BusError::Validation(r, _) if *r == reason)
}

fn obj(pairs: &[(&str, CValue)]) -> CValue {
    CValue::Obj(pairs.iter().map(|(k, v)| (k.to_string(), v.clone())).collect::<BTreeMap<_, _>>())
}

fn s(v: &str) -> CValue {
    CValue::Str(v.to_string())
}

/// AC-1: every row of `literals.csv` (at least 500 values) gives the expected bits or refusal.
#[test]
fn ac1_fixture_rows() {
    let cat = fixture_catalogue();
    let text = String::from_utf8(read("literals.csv")).unwrap();
    let mut lines = text.lines();
    assert_eq!(lines.next(), Some("literal,unit,kind,expected"));
    let (mut values, mut refusals, mut failures) = (0usize, 0usize, Vec::new());
    for (i, line) in lines.enumerate() {
        let f: Vec<&str> = line.split(',').collect();
        assert_eq!(f.len(), 4, "row {}: {line:?}", i + 2);
        let got = match run(f[0], f[1], f[2], &cat) {
            Ok(bits) => format!("{bits:016x}"),
            Err(e) => {
                assert_eq!(e.code(), Code::Validation, "row {}: {line:?}", i + 2);
                format!("error:{}", e.reason())
            }
        };
        if f[3].starts_with("error:") {
            refusals += 1;
        } else {
            values += 1;
        }
        if got != f[3] {
            failures.push(format!("row {}: {line:?} gave {got}", i + 2));
        }
    }
    assert!(failures.is_empty(), "{} rows differ:\n{}", failures.len(), failures.join("\n"));
    assert!(values >= 500, "only {values} value rows");
    assert!(refusals > 0);
}

/// AC-2: `10.1 mm` keeps its literal and gives the f64 nearest to 0.0101.
#[test]
fn ac2_literal_kept_and_one_rounding() {
    let lit = AuthoredLiteral::new("10.1", "mm").unwrap();
    let n = normalise(&lit, "length", &geo()).unwrap();
    assert_eq!(n.literal().to_value(), obj(&[("value", s("10.1")), ("unit", s("mm"))]));
    assert_eq!(to_canonical_bytes(&n.literal().to_value()).unwrap(), br#"{"unit":"mm","value":"10.1"}"#);
    assert_eq!(n.si_bits(), 0.0101f64.to_bits());
    assert_eq!(n.si_value(), CValue::Num(0.0101));
    assert_eq!(n.literal().value().as_str(), "10.1");
    assert_eq!(n.literal().unit().as_str(), "mm");
}

/// AC-3: `0.1 in` is the correctly rounded 0.00254. `0.3 in` shows the single rounding: two
/// roundings (0.3 then times 0.0254) land one ulp away from it.
#[test]
fn ac3_inch_single_rounding() {
    assert_eq!(run("0.1", "in", "length", &geo()).unwrap(), 0.00254f64.to_bits());
    let once = run("0.3", "in", "length", &geo()).unwrap();
    assert_eq!(once, 0.00762f64.to_bits());
    let twice = (0.3f64 * 0.0254f64).to_bits();
    assert_ne!(once, twice);
}

/// AC-4: `5 deg` for a length parameter is `validation` / `unit_mismatch`. `normalise` is
/// pure (it takes no journal or state), so the refusal journals nothing.
#[test]
fn ac4_unit_mismatch() {
    let e = run("5", "deg", "length", &geo()).unwrap_err();
    assert!(validation(ValidationReason::UnitMismatch)(&e), "{e}");
    assert_eq!(e.code().as_str(), "validation");
    assert_eq!(e.reason(), "unit_mismatch");
    // Unknown kinds, unknown units and badly shaped symbols are refused the same way.
    for (u, k) in [("mm", "angle"), ("mm", "mass"), ("MM", "length"), ("\u{b5}m", "length"), ("", "length")] {
        let e = run("5", u, k, &geo()).unwrap_err();
        assert!(validation(ValidationReason::UnitMismatch)(&e), "{u} {k}: {e}");
    }
}

/// AC-5: 65 significant digits are `literal_out_of_range`; 64 are accepted.
#[test]
fn ac5_too_many_digits() {
    let d64 = "9".repeat(MAX_SIG_DIGITS);
    let d65 = "9".repeat(MAX_SIG_DIGITS + 1);
    assert!(run(&d64, "nm", "length", &geo()).is_ok());
    let e = run(&d65, "nm", "length", &geo()).unwrap_err();
    assert!(validation(ValidationReason::LiteralOutOfRange)(&e), "{e}");
    // Leading zeros are not significant; trailing ones are.
    assert!(DecimalString::new(&format!("0.000{d64}")).is_ok());
    assert!(DecimalString::new(&format!("{d64}0")).is_err());
    // Exponent bounds (REQ-004).
    assert!(DecimalString::new("1e400").is_ok());
    assert!(DecimalString::new("1e-400").is_ok());
    assert!(validation(ValidationReason::LiteralOutOfRange)(&DecimalString::new("1e401").unwrap_err()));
    assert!(validation(ValidationReason::LiteralOutOfRange)(&DecimalString::new("1e-401").unwrap_err()));
}

/// AC-6, platform-independent part: the record of AC-2 (literal, SI bits, algorithm) is
/// byte-identical to the reference on every CI platform (Linux, Windows, macOS). The replay of
/// a journal entry that holds it needs `Bus::execute` (CORE.BUS.PIPE.STAGE) and is left to it.
#[test]
fn ac6_record_is_platform_independent() {
    let n = normalise(&AuthoredLiteral::new("10.1", "mm").unwrap(), "length", &geo()).unwrap();
    let record = obj(&[
        ("algorithm", s(&n.algorithm().to_string())),
        ("literal", n.literal().to_value()),
        ("si_hex", s(&format!("{:016x}", n.si_bits()))),
    ]);
    let want = read("ac2_record.json");
    let want = String::from_utf8(want).unwrap();
    assert_eq!(String::from_utf8(to_canonical_bytes(&record).unwrap()).unwrap(), want.trim_end());
    // Same literal, same bits, every time and with either catalogue path.
    let again = run("10.1", "mm", "length", &fixture_catalogue()).unwrap();
    assert_eq!(again, n.si_bits());
}

/// REQ-005: the algorithm ID.
#[test]
fn req5_algorithm_id() {
    let n = normalise(&AuthoredLiteral::new("1", "deg").unwrap(), "angle", &geo()).unwrap();
    assert_eq!(ALGORITHM, "core.unit.normalise@1.0.0");
    assert_eq!(n.algorithm().to_string(), ALGORITHM);
    assert_eq!(*n.algorithm(), algorithm_id());
}

/// The literal object VALID hands over: `{"value": "<decimal>", "unit": "<symbol>"}` only.
#[test]
fn literal_object_shape() {
    let cat = geo();
    let ok = obj(&[("value", s("12.7")), ("unit", s("um"))]);
    let n = normalise_value(&ok, "length", &cat).unwrap();
    assert_eq!(n.literal().to_value(), ok);
    let syntax = validation(ValidationReason::LiteralSyntax);
    for bad in [
        s("12.7 um"),
        CValue::Num(12.7),
        obj(&[("value", s("12.7"))]),
        obj(&[("value", CValue::Num(12.7)), ("unit", s("um"))]),
        obj(&[("value", s("12.7")), ("unit", CValue::Null)]),
        obj(&[("value", s("12.7")), ("unit", s("um")), ("note", s("x"))]),
        obj(&[("val", s("12.7")), ("unit", s("um"))]),
    ] {
        let e = normalise_value(&bad, "length", &cat).unwrap_err();
        assert!(syntax(&e), "{bad:?}: {e}");
    }
    // A well-shaped object with a bad decimal is still `literal_syntax`; a bad unit `unit_mismatch`.
    let e = normalise_value(&obj(&[("value", s(".5")), ("unit", s("um"))]), "length", &cat).unwrap_err();
    assert!(syntax(&e));
    let e = normalise_value(&obj(&[("value", s("5")), ("unit", s("deg"))]), "length", &cat).unwrap_err();
    assert!(validation(ValidationReason::UnitMismatch)(&e));
}

/// Fail closed: no infinity and no flush to zero.
#[test]
fn overflow_and_underflow_refused() {
    let out = validation(ValidationReason::LiteralOutOfRange);
    assert!(out(&run("1.7976931348623159e308", "m", "length", &geo()).unwrap_err()));
    assert!(out(&run("1e-330", "m", "length", &geo()).unwrap_err()));
    assert_eq!(run("1.7976931348623158e308", "m", "length", &geo()).unwrap(), f64::MAX.to_bits());
    assert_eq!(run("5e-324", "m", "length", &geo()).unwrap(), 1);
    assert_eq!(run("-0", "mm", "length", &geo()).unwrap(), (-0.0f64).to_bits());
    assert!(run("1e999999999999999999999", "m", "length", &geo()).is_err());
}

/// Checked constructors keep the literal exactly as written.
#[test]
fn as_entered() {
    let d = DecimalString::new("+007.50E-0").unwrap();
    assert_eq!(d.as_str(), "+007.50E-0");
    assert!(!d.is_negative() && !d.is_zero());
    assert!(DecimalString::new("-0.000").unwrap().is_zero());
    assert!(UnitSymbol::new("arcsec").is_ok());
    assert!(UnitSymbol::new("a b").is_err());
    let long = format!("0.{}1", "0".repeat(1100));
    assert!(validation(ValidationReason::LiteralOutOfRange)(&DecimalString::new(&long).unwrap_err()));
}
